from pathlib import Path

base = Path(r'c:\Users\anshg\.chakra\projects\C--Users-anshg--cursor-headless-harness-datagen-harness-chakra')
files = ['21f0ed91-5865-41a3-a95b-19a430a35234.jsonl','87d798e4-4729-48f5-9728-ddf32b56f49d.jsonl']

def parse_ts(ts):
    if not ts: return None
    if isinstance(ts,(int,float)):
        # ms or s
        v=float(ts)
        if v>1e12: v/=1000
        return datetime.utcfromtimestamp(v/1000 if v>1e12 else (v/1000 if v>1e11 else v))
    s=str(ts).replace('Z','+00:00')
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except: return None

for fn in files:
    path=base/fn
    types=collections.Counter(); tools=collections.Counter(); roles=collections.Counter()
    tool_calls=0; bash=0; thinking_blocks=0; thinking_chars=0; text_chars=0
    sleep_waits=0; unity=0; npm_install=0; long_cmds=[]
    first_ts=None; last_ts=None; timestamps=[]
    bash_cmds=[]
