        t=o.get('type') or o.get('type')
        types[t or 'unknown'] += 1
        ts=o.get('timestamp') or o.get('ts') or o.get('time')
        pt=parse_ts(ts)
        if pt:
            if first_ts is None: first_ts=pt
            last_ts=pt
        # nested message
        msg=o.get('message') or {}
