import json
from datetime import datetime
from pathlib import Path

def parse_ts(ts):
    return datetime.fromisoformat(str(ts).replace('Z','+00:00'))

base=Path(r'c:\Users\anshg\.chakra\projects\C--Users-anshg--cursor-headless-harness-datagen-harness-chakra')

def breakdown(fn):
    path=base/fn
    events=[]  # (ts, kind, detail)
    bash_starts={}
    # reconstruct: when Bash tool_use, then later tool_result or task-notification
    pending_bash=None
    asst_times=[]
    tool_result_times=[]
    background_wait=0.0
    # Walk chronologically: attribute gaps between consecutive events
    timeline=[]
    for line in path.open(encoding='utf-8', errors='replace'):
        o=json.loads(line)
        t=o.get('type'); ts=o.get('timestamp')
        if not ts: continue
        pt=parse_ts(ts)
        msg=o.get('message') or {}
        content=msg.get('content') if isinstance(msg,dict) else None
        if t=='assistant':
            names=[]
            if isinstance(content,list):
                for b in content:
                    if isinstance(b,dict) and b.get('type')=='tool_use':
                        names.append((b.get('name'), b.get('id'), (b.get('input') or {}).get('timeout'), str((b.get('input') or {}).get('command') or '')[:80]))
            timeline.append((pt,'assistant',names))
        elif t=='user':
            text=''
            is_tool=False
            if isinstance(content,list):
                for b in content:
                    if isinstance(b,dict) and b.get('type')=='tool_result':
                        is_tool=True
                    if isinstance(b,dict) and b.get('type')=='text':
                        text+=b.get('text') or ''
            elif isinstance(content,str):
                text=content
            kind='tool_result' if is_tool else ('task_notif' if 'task-notification' in text else 'user')
            timeline.append((pt,kind,text[:100]))

    # Estimate: time from assistant(with tools) to next user tool_result = tool time
    # time from tool_result/user to next assistant = LLM time
    llm=0.0; tools=0.0; other=0.0
    for i in range(len(timeline)-1):
        t0,k0,d0=timeline[i]
        t1,k1,d1=timeline[i+1]
        dt=(t1-t0).total_seconds()
        if dt<0: continue
        if k0 in ('tool_result','task_notif','user') and k1=='assistant':
            llm += dt
        elif k0=='assistant' and k1 in ('tool_result','task_notif'):
            tools += dt
        else:
            other += dt
    total=(timeline[-1][0]-timeline[0][0]).total_seconds()
    print(fn)
    print(f'  wall={total/60:.1f}m llm_gaps={llm/60:.1f}m tool_gaps={tools/60:.1f}m other={other/60:.1f}m')
    # Count write files and prompt size
    writes=0; prompt_len=0
    for line in path.open(encoding='utf-8', errors='replace'):
        o=json.loads(line)
        if o.get('type')=='user':
            msg=o.get('message') or {}
            c=msg.get('content')
            if isinstance(c,str) and c.startswith('#'):
                prompt_len=len(c)
        if o.get('type')=='assistant':
            msg=o.get('message') or {}
            for b in msg.get('content') or []:
                if isinstance(b,dict) and b.get('type')=='tool_use' and b.get('name')=='Write':
                    writes+=1
                    inp=b.get('input') or {}
                    content=inp.get('content') or inp.get('file_text') or ''
                    # track large writes
    print(f'  prompt_chars={prompt_len} writes={writes}')

